import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached in-memory bytes for Ai NoteZilla screenshots, banner and logo
class AiNoteZillaBytes {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String assetPath) {
    if (_cache.containsKey(assetPath)) return _cache[assetPath];
    final base64Str = _data[assetPath];
    if (base64Str == null) return null;
    final bytes = base64Decode(base64Str);
    _cache[assetPath] = bytes;
    return bytes;
  }

  static final Map<String, String> _data = {
    'assets/images/ai_notezilla_card_banner.png':
        '',
    'assets/images/ai_notezilla_logo.png':
        '',
    'assets/images/ai_notezilla/note_01_splash_screen.png':
        '',
    'assets/images/ai_notezilla/note_02_ai_smart_summarizer.png':
        '',
    'assets/images/ai_notezilla/note_03_smart_title_generator.png':
        '',
    'assets/images/ai_notezilla/note_04_flawless_clarity_tone.png':
        '',
    'assets/images/ai_notezilla/note_05_auth_sign_in.png':
        '',
    'assets/images/ai_notezilla/note_06_home_multimedia_dashboard.png':
        '',
    'assets/images/ai_notezilla/note_07_create_note_ai_assist.png':
        '',
    'assets/images/ai_notezilla/note_08_audio_memo_recording.png':
        '',
    'assets/images/ai_notezilla/note_09_video_note_camera.png':
        '',
    'assets/images/ai_notezilla/note_10_ai_assist_features.png':
        '',
    'assets/images/ai_notezilla/note_11_search_and_filter_notes.png':
        '',
    'assets/images/ai_notezilla/note_12_app_settings.png':
        '',
  };
}
